'use strict';
// Writes data.js next to this file: the demo package (collection.json plus every profile it lists)
// as window.MAP_PACKAGE, so the prototype opens from file:// without a server.
// Usage: node prototypes/map-view/embed-demo.js
const fs = require('fs');
const path = require('path');

const demo = path.join(__dirname, '..', '..', 'profiles', 'demo');
const collection = JSON.parse(fs.readFileSync(path.join(demo, 'collection.json'), 'utf8'));
const profiles = {};
for (const t of collection.topics) profiles[t.file] = JSON.parse(fs.readFileSync(path.join(demo, t.file), 'utf8'));

const out = '/* Generated by embed-demo.js from profiles/demo. Do not edit by hand. */\n'
  + 'window.MAP_PACKAGE=' + JSON.stringify({ collection, profiles }) + ';\n';
fs.writeFileSync(path.join(__dirname, 'data.js'), out);
console.log('wrote data.js (' + collection.topics.length + ' topics)');
